from restyle import EP,P,STYLE,CHARS,composite,request,save,run_queue
from PIL import Image,ImageOps
import json
FIXES={
'S03':('worker','MANDATORY VERY TIGHT physical hand-and-door close-up. Show ONLY one yellow rubber gloved hand and a short blue-grey sleeve pressing the inner edge of the old entrance door. Camera about 35 cm from hand. Door opens just a narrow gap; collapsed takeaway bags and boxes wedge the lower door edge from inside, no empty floor. Hand occupies central third, door edge and trapped waste occupy rest. Crop entirely excludes head, torso, legs, shoes and all other people. Do NOT show full room. No tiny full-body person.'),
'S11':('worker+partner','View from corridor looking through same rental doorway. EXACTLY THREE tied large black waste sacks sit TOGETHER OUTSIDE doorway in foreground left against corridor wall, not blocking exit. Inside, blue-grey cleaner and orange partner continue gathering loose waste near a folding table; ONLY small front corner of table has emerged, the rest still covered with takeaway boxes. Sofa and bed remain buried in large heaps. Key fact is three tied sacks outside versus barely changed interior. Keep actors secondary, scene medium-wide, no other sacks outside in frame.'),
'S15':('worker','MANDATORY TIGHT evidence CLOSE-UP at cabinet base. Cracked white takeaway container WEDGED UNDER cabinet FOOT, lid visibly broken in two, moist old food scraps have slid onto adjacent dirty floor. One yellow glove and a short blue-grey sleeve enter from left beside box, pulling it slightly; show ONLY hand, cabinet foot, broken box, scraps, floor and local hair/litter. Absolutely NO head, torso, whole person, legs or whole room. Camera 40cm from evidence; box fills middle half of frame.'),
'S45':('worker+partner+landlord','Preserve the supplied living-room composition and three people. Correct ONLY blue-grey worker hand anatomy: exactly TWO yellow gloved hands total, one raised near chin and the other naturally holding wrist across abdomen. REMOVE the extra dangling yellow glove-shaped object at right hip. Reconstruct blue-grey jacket hem and dark trousers there. Preserve orange partner inspecting sofa torn corner and purple landlord pointing. Tiny small black oval eyes, no extra hands or floating gloves.'),
'S46':('worker+landlord','Same sofa has been tilted forward enough to show a broad dark-stained underside fabric flap and visibly deformed yellow foam at its torn lower side, sofa stays on floor, no floating furniture. Blue-grey cleaner uses one yellow glove to indicate a small wiped upholstery patch at left and other yellow glove to indicate the dark deeply stained exposed foam/filling at right. Purple landlord beside him watches these TWO DIFFERENT MATERIAL CONDITIONS. Exactly two people, no partner. Folding table and iron bed under rear-right window remain. Do not show ordinary intact sofa with no evidence.'),
'S49':('worker+partner','Orange partner pauses to study exposed contamination, one pale-blue hand reaches toward a short scraper on floor. A broom stands UNUSED against wall, nobody holds broom or sweeps. Blue-grey cleaner kneels nearby with cloth. Sofa absent, iron bed and folding table present; dirty mat of litter and hair still visible. Exactly two people. Do not show a cleaner sweeping.'),
'S55':('worker','MANDATORY TIGHT hand-and-floor evidence CLOSE-UP. Show ONLY one yellow gloved hand and short blue-grey sleeve wiping boundary of a small repeatedly washed grey-brown floor patch with a clean cloth. Original floor color is emerging in wiped patch, adjacent floor still sticky and dark. Fresh water bucket and folded replacement cloth at one edge, not huge. No head, torso, legs, full person or whole room. Physical material detail and glove fill frame. No restored new flooring.')}
def fix(item,index):
 sid,(cast,change)=item;row=P['shots'][int(sid[1:])-1];ids=cast.split('+');src=EP/'image/final'/f'{sid}.png';ref=composite(src,ids,'round-fix-'+sid)
 prompt=STYLE+' Composite LEFT is current room and action reference, RIGHT identities: '+', '.join(ids)+'. Output ONE full frame, no reference strip. '+' '.join(CHARS[k] for k in ids)+'. REQUIRED CORRECTION: '+change+' Preserve same scene materials, daylight, dirty/clean stage, no text, cats, comic symbols or duplicated anatomy.'
 meta=dict(**row,stage='round-fact-correction',environment_master=json.loads((EP/'logs/requests'/f'{sid}.json').read_text())['metadata']['environment_master'],reason=change)
 raw=request('round-fix-'+sid,prompt,index,ref,meta)
 with Image.open(raw) as im:ImageOps.fit(im.convert('RGB'),(1920,1080),method=Image.Resampling.LANCZOS).save(src)
 d=json.loads((EP/'logs/requests'/f'round-fix-{sid}.json').read_text());save(EP/'logs/requests'/f'{sid}.json',d)
 print('FIXED',sid,flush=True)
if __name__=='__main__':run_queue(list(enumerate(FIXES.items())),fix)
